import { spawn } from 'node:child_process';
const p = spawn('/harness-state/.bun/bin/gbrain', ['serve','--surface','starter','--advertise','verbs'], { env: { ...process.env, GBRAIN_HOME: process.env.HOME }, stdio: ['pipe','pipe','pipe'] });
let buf = ''; const waiters = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0,i); buf = buf.slice(i+1); try { const m = JSON.parse(line); if (m.id != null && waiters.has(m.id)) { waiters.get(m.id)(m); waiters.delete(m.id); } } catch {} } });
p.stderr.on('data', d => process.stderr.write('[serve] ' + d));
const rpc = (method, params) => new Promise(r => { const n = ++id; waiters.set(n, r); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const short = o => JSON.stringify(o).slice(0, 1500);
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('INIT', init.result?.serverInfo, init.error);
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('TOOLS', tl.result?.tools?.map(t => t.name).join(','));
const fact = process.argv[2];
const rem = await rpc('tools/call', { name: 'remember', arguments: { fact, provenance: 'install-check' } });
console.log('REMEMBER', short(rem.result ?? rem.error));
const rec = await rpc('tools/call', { name: 'recall', arguments: { query: process.argv[3] } });
console.log('RECALL', short(rec.result ?? rec.error));
p.kill(); process.exit(0);

